from bisect import bisect_right


def coveredQueries(intervals, queries):
    starts = []
    ends = []
    for l, r in sorted(intervals):
        if ends and l <= ends[-1] + 1:
            if r > ends[-1]:
                ends[-1] = r
        else:
            starts.append(l)
            ends.append(r)
    res = []
    for a, b in queries:
        i = bisect_right(starts, a) - 1
        res.append(1 if i >= 0 and ends[i] >= b else 0)
    return res
